<section class="section-wrap cart-page"><div class="shop-heading"><p class="eyebrow">A FEW GOOD THINGS</p><h1>Your bag<span class="brand-dot">.</span></h1></div><?php if (!$items): ?><div class="empty-state"><span>◌</span><h2>Your bag is taking a quiet moment.</h2><p>Explore the collection and find something that feels right.</p><a class="button button-dark" href="<?= $e($base) ?>/shop">Explore the shop <span>↗</span></a></div><?php else: ?><div class="cart-layout"><div class="cart-list"><?php foreach ($items as $item): $p = $item['product']; ?><article class="cart-item"><a class="cart-thumb" href="<?= $e($base) ?>/product?id=<?= (int) $p['id'] ?>"><?php if ($p['image_url']): ?><img src="<?= $e($p['image_url']) ?>" alt=""><?php else: ?><span>✳</span><?php endif; ?></a><div class="cart-item-info"><a href="<?= $e($base) ?>/product?id=<?= (int) $p['id'] ?>"><b><?= $e($p['name']) ?></b></a><small><?= $item['size'] ? 'Size ' . $e($item['size']) : 'Everyday size' ?></small><div class="cart-item-actions"><form action="<?= $e($base) ?>/cart/update" method="post"><input type="hidden" name="csrf_token" value="<?= $e($csrf_token) ?>"><input type="hidden" name="product_id" value="<?= (int) $p['id'] ?>"><input type="hidden" name="size" value="<?= $e($item['size']) ?>"><input type="number" name="quantity" min="1" max="<?= (int) $p['stock'] ?>" value="<?= $item['quantity'] ?>" aria-label="Quantity"><button>Update</button></form><form action="<?= $e($base) ?>/cart/remove" method="post"><input type="hidden" name="csrf_token" value="<?= $e($csrf_token) ?>"><input type="hidden" name="product_id" value="<?= (int) $p['id'] ?>"><input type="hidden" name="size" value="<?= $e($item['size']) ?>"><button>Remove</button></form></div></div><strong><?= number_format($item['subtotal'], 2) ?> <small>JOD</small></strong></article><?php endforeach; ?></div><aside class="order-summary"><p class="eyebrow">A LITTLE SUMMARY</p><h2>Estimated subtotal</h2><div><span>Items</span><b><?= number_format($total, 2) ?> JOD</b></div><div><span>Delivery</span><span>Calculated with your address</span></div><hr><?php if (empty($user)): ?><p>Sign in or create an account to continue.</p><a class="button button-dark full-button" href="<?= $e($base) ?>/login">Sign in to checkout <span>↗</span></a><?php else: ?><form class="checkout-start" data-checkout-form data-base="<?= $e($base) ?>" data-items="<?= $e(json_encode(array_map(static fn ($item) => ['product_id' => $item['product']['id'], 'quantity' => $item['quantity'], 'size' => $item['size'] ?: null], $items), JSON_HEX_APOS | JSON_HEX_QUOT)) ?>"><label>Full name<input name="ship_name" required maxlength="100" value="<?= $e($_SESSION['name'] ?? '') ?>"></label><label>Phone<input name="ship_phone" required maxlength="30" autocomplete="tel"></label><label>Delivery address<input name="ship_address" required maxlength="255" autocomplete="street-address"></label><label>City<input name="ship_city" required maxlength="80"></label><button class="button button-dark full-button" type="submit">Continue to secure payment <span>↗</span></button><p class="checkout-message" aria-live="polite"></p></form><?php endif; ?><a class="text-link" href="<?= $e($base) ?>/shop">Keep exploring</a></aside></div><?php endif; ?></section>
